class CartActor(private val checkout: CheckoutService) {
    private val commands = Channel<CartCommand>(
        capacity = Channel.BUFFERED,
        onUndeliveredElement = { command ->
            if (command is CartCommand.Checkout) command.replyTo.cancel()
        }
    )
    private var started = false

    // The lifecycle owner explicitly starts exactly one run() call.
    suspend fun run() {
        check(!started) { "CartActor is single-use" }
        started = true
        var items = emptyList<Item>()
        try {
            for (command in commands) {
                when (command) {
                    is CartCommand.Add -> items = items + command.item
                    is CartCommand.Remove -> items = items.filterNot { it.id == command.id }
                    is CartCommand.Checkout -> {
                        try {
                            command.replyTo.complete(checkout.submit(items))
                        } catch (expected: IOException) {
                            command.replyTo.completeExceptionally(expected)
                        } finally {
                            // Cancellation/unexpected failure must release the waiter.
                            if (!command.replyTo.isCompleted) command.replyTo.cancel()
                        }
                    }
                }
            }
        } finally {
            commands.cancel() // Discard queued commands and cancel their replies.
        }
    }

    suspend fun add(item: Item) {
        commands.send(CartCommand.Add(item))
    }

    suspend fun checkout(): CheckoutResult {
        val reply = CompletableDeferred<CheckoutResult>()
        try {
            commands.send(CartCommand.Checkout(reply))
            return reply.await()
        } finally {
            reply.cancel() // A departed caller must not retain its reply waiter.
        }
    }

    fun close() { commands.close() } // Graceful drain while run() is still active.
}
